mapper.select:
SELECT user_id
FROM system_user_role
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}
  AND deleted = 0
ORDER BY user_id

mapper.update:
UPDATE system_user AS u
JOIN system_user_role AS relation
  ON relation.tenant_id = u.tenant_id
 AND relation.user_id = u.id
 AND relation.role_id = #{roleId}
 AND relation.deleted = 0
SET u.auth_epoch = u.auth_epoch + 1,
    u.updated_by = #{operatorId}
WHERE u.tenant_id = #{tenantId}
  AND u.deleted = 0

mapper.insert:
INSERT INTO system_role_data_scope
    (tenant_id, role_id, data_scope_id, organization_id, created_by, updated_by)
SELECT #{tenantId}, #{roleId}, id, #{organizationId}, #{operatorId}, #{operatorId}
FROM system_data_scope
WHERE tenant_id = #{tenantId}
  AND scope_code = #{scopeCode}
  AND status = 1
  AND deleted = 0
LIMIT 1

mapper.update:
UPDATE system_role
SET data_scope = #{scopeCode}, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{roleId}
  AND version = #{version}
  AND deleted = 0

