SELECT DISTINCT user.id FROM system_user AS user JOIN system_user_role AS user_role ON user_role.tenant_id = user.tenant_id AND user_role.user_id = user.id AND user_role.deleted = 0 JOIN system_role AS role ON role.tenant_id = user_role.tenant_id AND role.id = user_role.role_id AND role.status = 1 AND role.deleted = 0 WHERE user.tenant_id = #{tenantId} AND user.status = 1 AND user.deleted = 0 AND ( role.role_code IN ('ADMIN', 'SUPER_ADMIN') OR EXISTS ( SELECT 1 FROM system_role_menu AS role_menu WHERE role_menu.tenant_id = role.tenant_id AND role_menu.role_id = role.id AND role_menu.deleted = 0 AND role_menu.menu_id IN
#{menuId}
) ) ORDER BY user.id

