mapper.select:
SELECT COUNT(*) FROM system_dictionary_item
WHERE tenant_id = #{tenantId} AND dict_type_id = #{typeId}
  AND item_value = #{itemValue} AND deleted = 0

SELECT id, username, user_id, login_ip, user_agent, success, failure_reason, login_time FROM system_login_log WHERE tenant_id = #{tenantId} AND deleted = 0
AND (username LIKE CONCAT('%', #{keyword}, '%') OR login_ip LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY login_time DESC LIMIT #{offset}, #{pageSize}

SELECT id, user_id, username, request_method, request_path, request_ip, success, error_message, duration_ms, operation_time FROM system_operation_log WHERE tenant_id = #{tenantId} AND deleted = 0
AND (username LIKE CONCAT('%', #{keyword}, '%') OR request_path LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY operation_time DESC LIMIT #{offset}, #{pageSize}

SELECT id, business_type, business_id, original_name, stored_name, storage_path, content_type, extension, file_size, sha256, created_time FROM system_attachment WHERE tenant_id = #{tenantId} AND deleted = 0
AND original_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY created_time DESC LIMIT #{offset}, #{pageSize}
